export const xmlStatus = (records = ""): string => `<?xml version="1.0" encoding="utf-8"?><StatusOutput><WorkspaceStatus><Status><RepSpec><Server>synthetic.invalid</Server><Name>synthetic</Name></RepSpec><Changeset>0</Changeset></Status></WorkspaceStatus><WkConfigType>Branch</WkConfigType><WkConfigName>/synthetic</WkConfigName>${records ? `<Changes>${records}</Changes>` : ""}</StatusOutput>`;
